import{c as a,Q as s,j as t,m as n}from"./chunks/framework.DOi4mjdC.js";const i="/assets/%E7%9F%A9%E9%98%B5%E7%BC%96%E7%A8%8B%E6%B5%81%E7%A8%8B%E7%A4%BA%E6%84%8F%E5%9B%BE.i53NBJhw.png",l="/assets/Nd2Nz%E8%BD%AC%E6%8D%A2%E7%A4%BA%E6%84%8F%E5%9B%BE-3%E6%96%B0.Bn3mE3ZA.png",p="/assets/zh-cn_image_0000002533171617.Da6rIv-S.png",b=JSON.parse('{"title":"算子实现","description":"","frontmatter":{},"headers":[{"level":1,"title":"算子实现","slug":"算子实现"},{"level":2,"title":"实现流程","slug":"实现流程"},{"level":2,"title":"设置Shape信息","slug":"设置shape信息"},{"level":2,"title":"设置format格式","slug":"设置format格式"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/算子实现.md","filePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/算子实现.md"}'),o={name:"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/算子实现.md"};function r(c,e,g,d,h,m){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="算子实现" tabindex="-1">算子实现 <a class="header-anchor" href="#算子实现" aria-label="Permalink to &quot;算子实现&quot;">​</a></h1><h2 id="实现流程" tabindex="-1">实现流程 <a class="header-anchor" href="#实现流程" aria-label="Permalink to &quot;实现流程&quot;">​</a></h2><p>上文介绍了Matmul矩阵乘的数据切分方案和数据流。Ascend C提供一组Matmul高阶API，封装了这些常用的切分和数据搬运、计算的算法逻辑，方便用户快速实现Matmul矩阵乘法的运算操作。开发者在host侧通过调用API自动获取Tiling参数，该参数传递到kernel侧后，在初始化操作时传入，通过几个简单的API即可完成矩阵乘操作。完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/00_introduction/02_matrix/matmul_high_level_api" target="_blank" rel="noreferrer">LINK</a>。</p><p><strong>图 1</strong> 矩阵编程流程示意图<br><img src="'+i+`" alt="" title="矩阵编程流程示意图"></p><p>host侧自动获取Tiling参数的关键步骤介绍如下：</p><ol><li><p><strong>创建Tiling对象</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();</span></span>
<span class="line"><span>matmul_tiling::MultiCoreMatmulTiling tilingApi(*ascendcPlatform);</span></span></code></pre></div><p>传入硬件平台信息创建PlatformAscendC对象，然后创建Tiling对象，硬件平台信息可以通过GetPlatformInfo获取。</p></li><li><p><strong>设置参与Matmul运算的核数，A、B的内存逻辑位置、格式和数据类型。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tilingApi.SetDim(ascendcPlatform-&gt;GetCoreNumAic());  </span></span>
<span class="line"><span>tilingApi.SetAType(AscendC::TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16, false);</span></span>
<span class="line"><span>tilingApi.SetBType(AscendC::TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16, false);</span></span>
<span class="line"><span>tilingApi.SetCType(AscendC::TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);</span></span></code></pre></div></li><li><p><strong>设置矩阵shape信息。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tilingApi.SetOrgShape(M, N, K); // 设置原始完整的形状M、N、K</span></span>
<span class="line"><span>tilingApi.SetShape(M, N, K);</span></span></code></pre></div></li><li><p><strong>设置可用空间大小信息。</strong></p><p>设置Matmul计算时可用的L1 Buffer/L0C Buffer/Unified Buffer空间大小，-1表示AI处理器对应Buffer的大小。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tilingApi.SetBufferSpace(-1, -1, -1);</span></span></code></pre></div></li><li><p><strong>获取Tiling参数。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int64_t res = tilingApi.GetTiling(tilingData);</span></span>
<span class="line"><span>if (res == -1) {</span></span>
<span class="line"><span>    std::cout &lt;&lt; &quot;gen tiling failed&quot; &lt;&lt; std::endl;</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>Tiling参数的序列化保存等其他操作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint32_t tcubeTilingSize = tilingData.GetDataSize();</span></span>
<span class="line"><span>tilingData.SaveToBuffer(tilingBuf, tcubeTilingSize);</span></span></code></pre></div></li></ol><p>kernel侧使用Matmul API矩阵乘运算的具体步骤如下：</p><ol><li><p><strong>创建Matmul对象</strong></p><p>创建Matmul对象的示例如下：</p><ul><li>纯Cube模式（只有矩阵计算）场景下，建议在代码中定义ASCENDC_CUBE_ONLY宏，避免额外的性能开销。本节内容以纯Cube模式举例。</li><li>默认为MIX模式（包含矩阵计算和矢量计算），该场景下通常不定义ASCENDC_CUBE_ONLY宏，如果在程序中使用了ASCENDC_CUBE_ONLY宏，则必须使用ASCEND_IS_AIC宏和ASCEND_IS_AIV宏将Cube计算和Vector计算隔离开，更多内容请参考<a href="./../融合算子编程/融合算子编程.html">融合算子编程</a>。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; aType; </span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; bType; </span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; cType; </span></span>
<span class="line"><span>AscendC::Matmul&lt;aType, bType, cType&gt; mm;</span></span></code></pre></div><p>创建对象时需要传入A、B、C的参数类型信息， 类型信息通过MatmulType来定义，包括：内存逻辑位置、数据格式、数据类型。</p></li><li><p><strong>初始化操作。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling); // 初始化</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>Matmul高阶API内部实现时需要使用系统workspace（即对应本步骤中的GetSysWorkSpacePtr接口），开发者需要自行申请系统workspace的空间：</p><ul><li>在host侧Tiling实现时，设置总的workspace的数值大小（包含用户workspace和系统workspace），workspace空间由框架来申请并管理。系统workspace的空间大小通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/GetLibApiWorkSpaceSize.md" target="_blank" rel="noreferrer">GetLibApiWorkSpaceSize</a>获取。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>size_t userWorkspaceSize = 0;</span></span>
<span class="line"><span>size_t systemWorkspaceSize = static_cast&lt;size_t&gt;(ascendcPlatform.GetLibApiWorkSpaceSize());</span></span>
<span class="line"><span>size_t workspaceSize = userWorkspaceSize + systemWorkspaceSize;</span></span></code></pre></div><ul><li>若算子工程不是<a href="./../../../编程指南/附录/工程化算子开发/概述.html">自定义算子工程</a>，也不是带有<a href="./../../../编程指南/附录/基于样例工程完成Kernel直调.html#table481718169817">HAVE_WORKSPACE</a>编译宏的<a href="./../../../编程指南/附录/基于样例工程完成Kernel直调.html">Kernel直调算子工程</a>，框架不会自动设置workspace，需要在kernel侧的Matmul初始化前，通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetSysWorkSpace.md" target="_blank" rel="noreferrer">SetSysWorkSpace</a>设置系统workspace。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 使用Matmul时必须设置workspace空间    </span></span>
<span class="line"><span>SetSysWorkspace(workspace);</span></span>
<span class="line"><span>if (GetSysWorkSpacePtr() == nullptr) {</span></span>
<span class="line"><span>    return;</span></span>
<span class="line"><span>}</span></span></code></pre></div></div></li><li><p><strong>设置左矩阵A、右矩阵B。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mm.SetTensorA(gmA);    // 设置左矩阵A</span></span>
<span class="line"><span>mm.SetTensorB(gmB);    // 设置右矩阵B</span></span></code></pre></div></li><li><p><strong>完成矩阵乘操作。</strong></p><ul><li><p>调用Iterate完成单次迭代计算，叠加while循环完成单核全量数据的计算。Iterate方式，可以自行控制迭代次数，完成所需数据量的计算，方式比较灵活。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>while (mm.Iterate()) {   </span></span>
<span class="line"><span>    mm.GetTensorC(gmC); </span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>调用IterateAll完成单核上所有数据的计算。IterateAll方式，无需循环迭代，使用比较简单。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mm.IterateAll(gmC);</span></span></code></pre></div></li></ul></li><li><p><strong>结束矩阵乘操作。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mm.End();</span></span></code></pre></div></li></ol><h2 id="设置shape信息" tabindex="-1">设置Shape信息 <a class="header-anchor" href="#设置shape信息" aria-label="Permalink to &quot;设置Shape信息&quot;">​</a></h2><p>在实现Host Tiling时可以设置Shape信息，用于Tiling计算；kernel侧运行时也可以修改部分Shape信息，用于尾块设置、Matmul复用（多个Matmul计算复用一个Matmul对象）等场景。本节对涉及到的Shape概念进行介绍，并给出host侧和kernel侧设置Tiling信息的指导。</p><ul><li>orgShape：M、N、K</li><li>singleCoreShape：singleCoreM、singleCoreN、singleCoreK</li><li>singleShape：singleM、singleN、singleK</li><li>baseShape：baseM、baseN、baseK</li></ul><p>通过<a href="./基础知识.html#zh-cn_topic_0000001622194138_section68451031218">数据分块（Tiling）</a>的介绍我们已经了解了orgShape(M、N、K)，singleCoreShape(singleCoreM、singleCoreN、singleCoreK)，baseShape(baseM、baseN、baseK)的概念，如下图所示：</p><p><img src="`+l+'" alt=""></p><p>除此之外，单核的Matmul Tiling时，实际参与Matmul计算的shape可以是原始shape中的一部分，singleM, singleN, singleK用于表达实际参与Matmul计算的shape，如下图所示。在单核的情况下，singleM, singleN, singleK会透传给singleCoreM, singleCoreN, singleCoreK。</p><p><img src="'+p+`" alt=""></p><ul><li><p>Kernel运行时设置</p><ul><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetTail.md" target="_blank" rel="noreferrer">SetTail</a>、<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetSingleShape.md" target="_blank" rel="noreferrer">SetSingleShape</a>都是运行时修改singleCoreM、singleCoreN、singleCoreK，处理尾块时使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetTail.md" target="_blank" rel="noreferrer">SetTail</a>，Matmul复用（多个Matmul计算复用一个Matmul对象）的场景可以使用SetSingleShape重新设置。</li><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetOrgShape.md" target="_blank" rel="noreferrer">SetOrgShape</a>是运行时修改M、N、K，Matmul复用的场景可以使用SetOrgShape重新设置。</li></ul></li><li><p>单核Tiling时设置</p><ul><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetOrgShape-31.md" target="_blank" rel="noreferrer">SetOrgShape</a>（必选）：设置M、N、K</li><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetShape.md" target="_blank" rel="noreferrer">SetShape</a>（非必选）： 设置singleM、singleN、singleK，等同于设置singleCoreM、singleCoreN、singleCoreK</li><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetFixSplit.md" target="_blank" rel="noreferrer">SetFixSplit</a>（非必选）：设置baseM、baseN、baseK</li></ul></li><li><p>多核Tiling时设置</p><ul><li><p><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetOrgShape-31.md" target="_blank" rel="noreferrer">SetOrgShape</a>（必选）：设置M、N、K</p></li><li><p><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetShape.md" target="_blank" rel="noreferrer">SetShape</a>（非必选）： 设置singleM、singleN、singleK</p></li><li><p><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetFixSplit.md" target="_blank" rel="noreferrer">SetFixSplit</a>（非必选）：设置baseM、baseN、baseK</p></li><li><p><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetSingleShape-30.md" target="_blank" rel="noreferrer">SetSingleShape</a>(非必选)： 设置singleCoreM、singleCoreN、singleCoreK</p></li><li><p><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetSingleRange.md" target="_blank" rel="noreferrer">SetSingleRange</a>(非必选) ：设置singleCoreM、singleCoreN、singleCoreK的范围</p></li></ul></li></ul><h2 id="设置format格式" tabindex="-1">设置format格式 <a class="header-anchor" href="#设置format格式" aria-label="Permalink to &quot;设置format格式&quot;">​</a></h2><p>创建Matmul对象时需要传入A、B、C的参数类型信息， 类型信息通过MatmulType来定义，包括：内存逻辑位置、数据格式、数据类型。示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; aType; </span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; bType; </span></span>
<span class="line"><span>typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; cType; </span></span>
<span class="line"><span>AscendC::Matmul&lt;aType, bType, cType&gt; mm;</span></span></code></pre></div><p>针对数据格式，包括CubeFormat::ND, CubeFormat::NZ, CubeFormat::ND_ALIGN三种，ND和NZ格式在<a href="./基础知识.html#zh-cn_topic_0000001622194138_section1453415011">数据格式</a>章节已经介绍，ND_ALIGN格式的介绍请参考<a href="./../../../编程指南/概念原理和术语/神经网络和算子/数据排布格式.html#li075920427155">数据排布格式</a>。</p>`,20)])])}const S=a(o,[["render",r]]);export{b as __pageData,S as default};
